// The turn rules: what one conversation's frame stream means for the turn —
// the tyger decision layer's rule half, ported 1:1 from
// crates/idfon-voice/src/turns.rs (itself a byte-identical port of tyger-s2s
// app/plugins/ears/tyger/{rules,session,constants}.py).
//
// Parity: test/rules.test.ts replays crates/idfon-voice/tests/data/turns-fixtures.json
// (generated by scripts/tyger-rules-fixtures.py from the Python oracle) and asserts
// byte-identical events, the same contract the Rust port passes.

export const SR = 16000;
export const FRAME_S = 0.08; // one encoder frame (12.5 Hz) = one decision
export const HOP_FRAMES = 4; // frames per hop (320 ms)
export const HOP_N = 5120;
export const WINDOW_S = 8.0;

export const LISTEN = 0;
export const HOLD = 1;
export const SPEAK = 2;
export const BACKCHANNEL = 3;
export const STATE_NAMES = ["LISTEN", "HOLD", "SPEAK", "BACKCHANNEL"];

export const VAD_DB = -50.0;
export const MIN_SPEECH_MS = 350.0;
export const WARMUP_FRAMES = 6;
export const BARGE_PRE_S = 2.0;
export const ONSET_GAP_FRAMES = 8;
export const ONSET_MAX_S = 4.0;

export interface Thresholds {
  ep_thr: number;
  ep_deb: number;
  barge_thr: number;
  barge_deb: number;
  bc_thr: number;
  bc_deb: number;
  theta: number;
  bc_refractory: number;
}

export const DEFAULT_THRESHOLDS: Thresholds = {
  ep_thr: 0.9146,
  ep_deb: 2,
  barge_thr: 0.5,
  barge_deb: 2,
  bc_thr: 0.5,
  bc_deb: 2,
  theta: 0.2,
  bc_refractory: 15,
};

export interface Event {
  kind: string;
  state?: string;
  yield_prob?: number;
  hazard?: number;
  bc_prob?: number;
  p_end?: number;
  onset_s?: number;
  partial?: string;
  turn_s?: number;
  segments?: number;
  by?: string;
  text?: string;
  transcript?: string | null;
  seg_texts?: (string | null)[];
}

function ev(kind: string): Event {
  return { kind };
}

/// Per-80 ms-frame energy in dB (rules.frame_energy). `wav` is 16 kHz f32.
export function frameEnergy(wav: ArrayLike<number>): number[] {
  const hop = Math.round(FRAME_S * SR);
  const n = Math.floor(wav.length / hop);
  const out: number[] = [];
  for (let i = 0; i < n; i++) {
    let sum = 0;
    for (let j = i * hop; j < (i + 1) * hop; j++) sum += wav[j] * wav[j];
    const mean = sum / hop;
    out.push(20 * Math.log10(Math.sqrt(mean + 1e-12) + 1e-9));
  }
  return out;
}

/// The 4-way state head's decision (rules.state_decision).
export function stateDecision(
  stateLogits: number[], hazard: number, prev: number, theta: number,
): number {
  const m = Math.max(...stateLogits);
  const e = stateLogits.map((l) => Math.exp(l - m));
  const s = e.reduce((a, b) => a + b, 0);
  const p = e.map((v) => v / s);
  const pmax = Math.max(...p);
  if ((prev === LISTEN || prev === HOLD) && p[BACKCHANNEL] >= 0.5 && p[BACKCHANNEL] === pmax) {
    return BACKCHANNEL;
  }
  if (prev === LISTEN || prev === HOLD) {
    if (hazard >= theta) return SPEAK;
    return p[HOLD] > p[LISTEN] ? HOLD : LISTEN;
  }
  if (prev === SPEAK) {
    return p[SPEAK] >= Math.max(p[LISTEN], p[HOLD]) ? SPEAK : LISTEN;
  }
  if (prev === BACKCHANNEL) {
    return p[BACKCHANNEL] === pmax ? BACKCHANNEL : LISTEN;
  }
  return LISTEN;
}

/// Python's `round(x, n)` (ties-to-even): the fixtures were rounded that way.
function bumpDecimal(head: string, n: number): string {
  const digits = head.split("");
  let i = digits.length - 1;
  while (i >= 0) {
    if (digits[i] === ".") { i--; continue; }
    if (digits[i] !== "9") { digits[i] = String(Number(digits[i]) + 1); break; }
    digits[i] = "0";
    i--;
  }
  if (i < 0 || digits[i] === ".") digits.unshift("1");
  return digits.join(""); // the dot stays where it is; a carry shifts it naturally
}

export function r(x: number, n: number): number {
  if (!Number.isFinite(x)) return x;
  const neg = x < 0;
  const s = Math.abs(x).toFixed(n + 12); // decimal expansion of the binary value
  const dot = s.indexOf(".");
  const head = s.slice(0, dot + 1 + n);
  const next = s[dot + 1 + n] ?? "0";
  const rest = s.slice(dot + 2 + n);
  const up = next > "5" || (next === "5" && (/[1-9]/.test(rest) || Number(head[head.length - 1]) % 2 === 1));
  const out = Number(up ? bumpDecimal(head, n) : head);
  return neg ? -out : out;
}

function slide(win: number[], hop: ArrayLike<number>, cap: number): void {
  for (let i = 0; i < hop.length; i++) win.push(hop[i]);
  if (win.length > cap) win.splice(0, win.length - cap);
}

export class TurnSession {
  th: Thresholds;
  win_u: number[] = [];
  win_a: number[] = [];
  turn_u: number[] = [];
  pre_u: number[] = [];
  seed_u: number[] | null = null;
  seg_s = 0;
  segs: (string | null)[] = [];
  words = "";
  turn_gen = 0;
  prev_state = LISTEN;
  voiced_ms = 0;
  in_turn = false;
  partial_asr = "";

  private talk_frames = 0;
  private quiet_frames = 0;
  private yield_run = 0;
  private warm = 0;
  private mode = "listen";
  private bc_run = 0;
  private bc_cooldown = 0;
  private ep_run = 0;
  private words_sent = "";
  private pending_reset = true;

  constructor(th: Partial<Thresholds> = {}) {
    this.th = { ...DEFAULT_THRESHOLDS, ...th };
    this.clear();
  }

  private clear(): void {
    this.win_u = [];
    this.win_a = [];
    this.turn_u = [];
    this.seg_s = 0;
    this.segs = [];
    this.pre_u = [];
    this.seed_u = null;
    this.talk_frames = 0;
    this.quiet_frames = 0;
    this.prev_state = LISTEN;
    this.yield_run = 0;
    this.voiced_ms = 0;
    this.in_turn = false;
    this.warm = 0;
    this.mode = "listen";
    this.bc_run = 0;
    this.bc_cooldown = 0;
    this.ep_run = 0;
    this.partial_asr = "";
    this.words = "";
    this.words_sent = "";
  }

  turnLenS(): number {
    return this.seg_s + this.turn_u.length / SR;
  }

  /// Applied by the caller's thread before the next hop.
  reset(): void {
    this.pending_reset = true;
  }

  /// Before a hop's frames: pending reset, window sliding, turn audio. True if
  /// the heads' context must start over (rules.begin_hop).
  begin_hop(userHop: ArrayLike<number>, agentHop: ArrayLike<number>, mode: string): boolean {
    const reset = this.pending_reset;
    if (reset) {
      const seed = this.seed_u;
      this.clear();
      this.turn_gen += 1;
      this.pending_reset = false;
      if (seed) {
        // a barge-in: the new turn starts with the user's speech so far (I-02)
        this.voiced_ms =
          frameEnergy(seed).filter((e) => e > VAD_DB).length * FRAME_S * 1e3;
        this.in_turn = this.voiced_ms > 0;
        this.turn_u = seed;
      }
    }
    this.seed_u = null;
    slide(this.win_u, userHop, WINDOW_S * SR);
    slide(this.win_a, agentHop, WINDOW_S * SR);
    if (mode === "listen") {
      for (let i = 0; i < userHop.length; i++) this.turn_u.push(userHop[i]);
    } else {
      slide(this.pre_u, userHop, BARGE_PRE_S * SR);
    }
    return reset;
  }

  /// A change between listening and speaking: fresh decision runs (rules.switch_mode).
  switch_mode(mode: string): boolean {
    if (mode === this.mode) return false;
    this.warm = 0;
    this.yield_run = 0;
    this.bc_run = 0;
    this.bc_cooldown = 0;
    this.ep_run = 0;
    this.talk_frames = 0;
    this.quiet_frames = 0;
    this.prev_state = mode === "speaking" ? SPEAK : LISTEN;
    this.mode = mode;
    return true;
  }

  /// The user's words so far (set on the ASR thread): a PARTIAL event when changed.
  words_event(mode: string): Event | null {
    if (mode !== "listen" || this.words === this.words_sent) return null;
    this.words_sent = this.words;
    const e = ev("PARTIAL");
    e.text = this.words;
    return e;
  }

  private track_talk(voiced: boolean): void {
    if (this.talk_frames !== 0) {
      this.talk_frames += 1;
      this.quiet_frames = voiced ? 0 : this.quiet_frames + 1;
      if (this.quiet_frames > ONSET_GAP_FRAMES) {
        this.talk_frames = 0;
        this.quiet_frames = 0;
      }
    } else if (voiced) {
      this.talk_frames = 1;
      this.quiet_frames = 0;
    }
  }

  /// One frame's decision (rules.on_frame). `outputs` = the 8-vector (state
  /// logits x4, hazard, yield, bc, p_end); `left` = the hop's frames after this
  /// one (a barge's onset counts to the hop's end).
  on_frame(
    mode: string, outputs: number[], actDb: number, left: number,
  ): { events: Event[]; final: { event: Event; audio: number[] } | null; reset: boolean } {
    const events: Event[] = [];
    const slog = outputs.slice(0, 4);
    const [haz, yp, bcp, pep] = [outputs[4], outputs[5], outputs[6], outputs[7]];
    const st = stateDecision(slog, haz, this.prev_state, this.th.theta);
    const voiced = actDb > VAD_DB;

    if (mode === "speaking") {
      // BARGE path (yield head)
      this.warm += 1;
      this.track_talk(voiced);
      if (this.warm > WARMUP_FRAMES) {
        this.yield_run = yp >= this.th.barge_thr ? this.yield_run + 1 : 0;
        if (this.yield_run >= this.th.barge_deb) {
          const onset_s = this.talk_frames !== 0
            ? Math.min((this.talk_frames + left) * FRAME_S, ONSET_MAX_S)
            : 0;
          const e = ev("BARGE");
          e.yield_prob = r(yp, 3);
          e.onset_s = r(onset_s, 2);
          events.push(e);
          this.yield_run = 0;
          this.seed_u = this.pre_u.slice();
        }
      }
      const fr = ev("FRAME");
      fr.state = "SPEAK";
      fr.yield_prob = r(yp, 3);
      fr.hazard = r(haz, 3);
      fr.p_end = r(pep, 3);
      events.push(fr);
      this.prev_state = SPEAK;
      return { events, final: null, reset: false };
    }

    // LISTEN mode
    this.warm += 1;
    if (voiced) {
      this.voiced_ms += FRAME_S * 1e3;
      this.in_turn = true;
    }
    if (this.bc_cooldown > 0) {
      this.bc_cooldown -= 1;
      this.bc_run = 0;
    } else if (this.in_turn && this.voiced_ms >= MIN_SPEECH_MS && this.warm > WARMUP_FRAMES) {
      this.bc_run = bcp >= this.th.bc_thr ? this.bc_run + 1 : 0;
      if (this.bc_run >= this.th.bc_deb) {
        const e = ev("BACKCHANNEL");
        e.partial = this.partial_asr;
        e.bc_prob = r(bcp, 3);
        e.turn_s = r(this.turnLenS(), 2);
        events.push(e);
        this.bc_run = 0;
        this.bc_cooldown = this.th.bc_refractory;
      }
    }
    if (this.warm > WARMUP_FRAMES) {
      this.ep_run = pep >= this.th.ep_thr ? this.ep_run + 1 : 0;
    } else {
      this.ep_run = 0;
    }
    const spoke = this.in_turn && this.voiced_ms >= MIN_SPEECH_MS;
    if (spoke && this.ep_run >= this.th.ep_deb) {
      const e = ev("ENDPOINT");
      e.transcript = null;
      e.turn_s = this.turnLenS();
      e.segments = this.segs.length;
      e.seg_texts = this.segs.slice();
      e.by = "head";
      e.p_end = r(pep, 3);
      const final_audio = this.turn_u;
      this.turn_u = []; // Rust: mem::take — the turn's audio leaves with the event
      events.push({ ...e });
      this.voiced_ms = 0;
      this.in_turn = false;
      this.seg_s = 0;
      this.segs = [];
      this.prev_state = LISTEN;
      this.warm = 0;
      this.bc_run = 0;
      this.bc_cooldown = 0;
      this.ep_run = 0;
      this.partial_asr = "";
      this.turn_gen += 1;
      this.words = "";
      this.words_sent = "";
      const fr = ev("FRAME");
      fr.state = "idle";
      fr.yield_prob = r(yp, 3);
      fr.hazard = r(haz, 3);
      fr.bc_prob = r(bcp, 3);
      fr.p_end = r(pep, 3);
      events.push(fr);
      return { events, final: { event: e, audio: final_audio }, reset: true };
    }
    const disp = this.in_turn
      ? STATE_NAMES[st]
      : !voiced ? "idle" : "LISTEN";
    const fr = ev("FRAME");
    fr.state = disp;
    fr.yield_prob = r(yp, 3);
    fr.hazard = r(haz, 3);
    fr.bc_prob = r(bcp, 3);
    fr.p_end = r(pep, 3);
    events.push(fr);
    this.prev_state = LISTEN; // free-run: the ep head's operating regime
    return { events, final: null, reset: false };
  }
}
